273		j, err = s.Submit(SubmitRequest{
274			Submitter: "a", RequestID: "k", Values: []int64{7, -2},
275			Dependencies: []uint64{u2.ID, u1.ID},
276		})
277		if !errors.Is(err, ErrIdempotencyConflict) || j == nil || j.ID != orig.ID {
278			t.Fatalf("dependency-order swap despite identical sums must conflict: %v %+v", err, j)
279		}
280		// 两种冲突请求都不能新增作业：归档里只有 u1、u2、orig 三个作业。
281		if got, _ := s.List("a", time.Time{}, time.Time{}); len(got) != 3 {
282			t.Fatalf("conflicting replays created records: list len=%d want 3", len(got))
283		}
284		// 原作业的参数与成功归档保持不变。
285		g := waitStatus(t, s, orig.ID, StatusSucceeded)
286		assertInt64s(t, "original values", g.Values, []int64{7, -2})
287		assertUint64s(t, "original dependencies", g.Dependencies, []uint64{u1.ID, u2.ID})
288		assertInt64s(t, "original effective", g.Archive.EffectiveValues, wantEffective)
289		if g.Archive.Sum != 11 || g.Archive.SumOfSquares != 71 {
290			t.Fatalf("original archive altered: sum=%d sq=%d", g.Archive.Sum, g.Archive.SumOfSquares)
