1	package numeric
2	
3	import (
4		"encoding/json"
5		"errors"
6		"strings"
7		"testing"
8		"time"
9		"unicode/utf8"
10	)
11	
12	// 三个“看起来可能一样”、但字节互不相同的非空请求号：
13	// 单字节 0xFF、单字节 0xFE（二者都不是合法 UTF-8），以及替换字符
14	// U+FFFD 的合法 UTF-8 编码 EF BF BD。旧实现落盘后前两者都会被
15	// encoding/json 改写成 U+FFFD，三个标识在重新打开归档后塌缩成同一个。
16	var invalidUTF8Requests = []string{"\xff", "\xfe", "\uFFFD"}
17	
18	// 中文标识、零字符与非法 UTF-8 字节混排，确认保真规则不是只对单字节生效。
19	var mixedIdentitySub = "提交人\xff\x00尾"
20	var mixedIdentityReq = "请求\xfe号\x00\xff"
21	
22	func TestInvalidUTF8RequestsAreDistinctBeforeReopen(t *testing.T) {
23		s, _ := openTestStore(t)
24		sub := "alice"
25		var ids []uint64
26		for _, req := range invalidUTF8Requests {
27			j := mustSubmit(t, s, SubmitRequest{
28				Submitter: sub, RequestID: req,
29				Values: []int64{1, 2, 3}, Seed: 9,
30			})
31			ids = append(ids, j.ID)
32		}
33		for i := 1; i < len(ids); i++ {
34			if ids[i] == ids[0] {
35				t.Fatalf("请求号 %x 与 %x 串用同一作业号 %d",
36					invalidUTF8Requests[i], invalidUTF8Requests[0], ids[0])
37			}
38		}
39		for i, req := range invalidUTF8Requests {
40			d := waitStatus(t, s, ids[i], StatusSucceeded)
41			if d.Submitter != sub || d.RequestID != req {
42				t.Fatalf("作业 %d 标识失真：%x / %x，要 %x / %x",
43					ids[i], d.Submitter, d.RequestID, sub, req)
44			}
45		}
46	}
47	
48	// TestInvalidUTF8IdentitySurvivesReopen 是核心回归：关闭再打开同一归档后，
49	// 按作业号查到的提交人、请求号与提交时逐字节一致，归档中的参数同样一致，
50	// 作业号/状态/原始数值参数/结果摘要/日志/校验值都不因保存方式改变。
51	func TestInvalidUTF8IdentitySurvivesReopen(t *testing.T) {
52		dir := t.TempDir()
53		s, err := Open(dir)
54		if err != nil {
55			t.Fatal(err)
56		}
57	
58		type submitted struct {
59			req SubmitRequest
60			id  uint64
61		}
62		var jobs []submitted
63		for _, req := range invalidUTF8Requests {
64			r := SubmitRequest{
65				Submitter: "bob", RequestID: req,
66				Values: []int64{2, 4, -1, 7}, Seed: 99,
67			}
68			j := mustSubmit(t, s, r)
69			jobs = append(jobs, submitted{req: r, id: j.ID})
70		}
71		// 再提交一个混合标识（中文 + 非法字节 + 零字符）的作业。
72		mixed := SubmitRequest{
73			Submitter: mixedIdentitySub, RequestID: mixedIdentityReq,
74			Values: []int64{5, -5}, Seed: 13,
75		}
76		mj := mustSubmit(t, s, mixed)
77	
78		snapshot := map[uint64]*Job{}
79		for _, p := range jobs {
80			snapshot[p.id] = waitStatus(t, s, p.id, StatusSucceeded)
81		}
82		snapshot[mj.ID] = waitStatus(t, s, mj.ID, StatusSucceeded)
83	
84		if err := s.Close(); err != nil {
85			t.Fatal(err)
86		}
87		s2, err := Open(dir)
88		if err != nil {
89			t.Fatal(err)
90		}
91		defer s2.Close()
92	
93		for _, p := range jobs {
94			before := snapshot[p.id]
95			g, err := s2.Get(p.id)
96			if err != nil {
97				t.Fatal(err)
98			}
99			if g.Submitter != p.req.Submitter || g.RequestID != p.req.RequestID {
100				t.Fatalf("作业 %d 重开后标识失真：%x / %x，要 %x / %x",
101					p.id, g.Submitter, g.RequestID, p.req.Submitter, p.req.RequestID)
102			}
103			if g.Status != before.Status || g.Seed != before.Seed ||
104				len(g.Values) != len(before.Values) {
105				t.Fatalf("作业 %d 状态/原始参数被改写：%+v", p.id, g)
106			}
107			for i := range before.Values {
108				if g.Values[i] != before.Values[i] {
109					t.Fatalf("作业 %d 原始数值参数被改写", p.id)
110				}
111			}
112			if g.Archive == nil {
113				t.Fatalf("作业 %d 重开后丢失成功归档", p.id)
114			}
115			if g.Archive.Submitter != p.req.Submitter || g.Archive.RequestID != p.req.RequestID {
116				t.Fatalf("作业 %d 归档标识失真：%x / %x",
117					p.id, g.Archive.Submitter, g.Archive.RequestID)
118			}
119			if g.Archive.Sum != before.Archive.Sum ||
120				g.Archive.SumOfSquares != before.Archive.SumOfSquares ||
121				g.Archive.ResultDigest != before.Archive.ResultDigest ||
122				g.Archive.InputsDigest != before.Archive.InputsDigest ||
123				g.Archive.Log != before.Archive.Log ||
124				g.Archive.Checksum != before.Archive.Checksum {
125				t.Fatalf("作业 %d 的结果摘要/日志/校验值被改写", p.id)
126			}
127		}
128		mg, err := s2.Get(mj.ID)
129		if err != nil {
130			t.Fatal(err)
131		}
132		if mg.Submitter != mixed.Submitter || mg.RequestID != mixed.RequestID {
133			t.Fatalf("混合标识作业重开后失真：%x / %x，要 %x / %x",
134				mg.Submitter, mg.RequestID, mixed.Submitter, mixed.RequestID)
135		}
136		if mg.Archive == nil ||
137			mg.Archive.Submitter != mixed.Submitter || mg.Archive.RequestID != mixed.RequestID {
138			t.Fatalf("混合标识作业归档失真：%+v", mg.Archive)
139		}
140	}
141	
142	// TestInvalidUTF8IdempotencyAfterReopen ：重开后用原请求重放必须返回各自
143	// 原作业号且不新增记录；用已用请求号提交不同整数序列或种子，仍是既有的
144	// 幂等冲突错误，视图指向该请求自己的原作业，原记录保留。
145	func TestInvalidUTF8IdempotencyAfterReopen(t *testing.T) {
146		dir := t.TempDir()
147		s, err := Open(dir)
148		if err != nil {
149			t.Fatal(err)
150		}
151		sub := "carol"
152		baseReq := []SubmitRequest{
153			{Submitter: sub, RequestID: invalidUTF8Requests[0], Values: []int64{1, 2}, Seed: 4},
154			{Submitter: sub, RequestID: invalidUTF8Requests[1], Values: []int64{1, 2}, Seed: 4},
155			{Submitter: sub, RequestID: invalidUTF8Requests[2], Values: []int64{1, 2}, Seed: 4},
156		}
157		var baseIDs []uint64
158		for _, r := range baseReq {
159			baseIDs = append(baseIDs, mustSubmit(t, s, r).ID)
160		}
161		for _, id := range baseIDs {
162			waitStatus(t, s, id, StatusSucceeded)
163		}
164		if err := s.Close(); err != nil {
165			t.Fatal(err)
166		}
167		s2, err := Open(dir)
168		if err != nil {
169			t.Fatal(err)
170		}
171		defer s2.Close()
172	
173		for i, r := range baseReq {
174			replay, err := s2.Submit(r)
175			if err != nil || replay.ID != baseIDs[i] || replay.Status != StatusSucceeded {
176				t.Fatalf("请求 %x 重放：id=%d status=%s err=%v，要原作业 %d",
177					r.RequestID, replayID(replay), replay.Status, err, baseIDs[i])
178			}
179		}
180	
181		// 用 0xFF 请求号提交不同内容 → 冲突，且视图是 0xFF 自己的原作业，
182		// 不能返回 0xFE 或 U+FFFD 的作业（旧实现会在这里串用）。
183		conflictOwner := baseIDs[0]
184		variants := []SubmitRequest{
185			{Submitter: sub, RequestID: invalidUTF8Requests[0], Values: []int64{2, 1}, Seed: 4},
186			{Submitter: sub, RequestID: invalidUTF8Requests[0], Values: []int64{1, 2}, Seed: 5},
187		}
188		for i, v := range variants {
189			j, err := s2.Submit(v)
190			if !errors.Is(err, ErrIdempotencyConflict) {
191				t.Fatalf("变体 %d：err=%v，要幂等冲突", i, err)
192			}
193			if j == nil || j.ID != conflictOwner {
194				owned := uint64(0)
195				if j != nil {
196					owned = j.ID
197				}
198				t.Fatalf("变体 %d 冲突视图指向作业 %d，要 %d", i, owned, conflictOwner)
199			}
200			if j.RequestID != invalidUTF8Requests[0] || j.Submitter != sub {
201				t.Fatalf("变体 %d 冲突视图标失真：%x / %x",
202					i, j.Submitter, j.RequestID)
203			}
204		}
205		// 原记录保留：三个请求各自仍只对应一个作业。
206		if got, _ := s2.List(sub, time.Time{}, time.Time{}); len(got) != len(baseReq) {
207			var ids []uint64
208			for _, j := range got {
209				ids = append(ids, j.ID)
210			}
211			t.Fatalf("冲突/重放不应改变记录数，List=%v，要 %d 条", ids, len(baseReq))
212		}
213	
214		// 0xFE 的原请求号正常重放仍命中它自己的作业，与上面的冲突互不相干。
215		rep, err := s2.Submit(baseReq[1])
216		if err != nil || rep.ID != baseIDs[1] {
217			t.Fatalf("0xFE 重放被 0xFF 的冲突污染：id=%d err=%v，要 %d",
218				replayID(rep), err, baseIDs[1])
219		}
220	}
221	
222	// TestInvalidUTF8SubmitterScopesRequestIDs ：提交人含非法 UTF-8 字节时，
223	// 字节不同的提交人不得共用请求号作用域；重开后仍然隔离。按提交人列举也
224	// 必须完整字符串匹配，显示相似不能混入别人的作业。
225	func TestInvalidUTF8SubmitterScopesRequestIDs(t *testing.T) {
226		dir := t.TempDir()
227		s, err := Open(dir)
228		if err != nil {
229			t.Fatal(err)
230		}
231		submitters := []string{"\xff", "\xfe", "\uFFFD", "中文\xff人"}
232		commonReq := "shared\x00id"
233		owner := map[string]uint64{}
234		for _, sub := range submitters {
235			j := mustSubmit(t, s, SubmitRequest{
236				Submitter: sub, RequestID: commonReq,
237				Values: []int64{3, 4}, Seed: 1,
238			})
239			owner[sub] = j.ID
240		}
241		seen := map[uint64]struct{}{}
242		for sub, id := range owner {
243			if _, dup := seen[id]; dup {
244				t.Fatalf("不同提交人串用作业号 %d（提交人 %x）", id, sub)
245			}
246			seen[id] = struct{}{}
247			waitStatus(t, s, id, StatusSucceeded)
248		}
249		if err := s.Close(); err != nil {
250			t.Fatal(err)
251		}
252		s2, err := Open(dir)
253		if err != nil {
254			t.Fatal(err)
255		}
256		defer s2.Close()
257	
258		for _, sub := range submitters {
259			// 同提交人同请求号 → 自己的原作业。
260			j, err := s2.Submit(SubmitRequest{
261				Submitter: sub, RequestID: commonReq,
262				Values: []int64{3, 4}, Seed: 1,
263			})
264			if err != nil || j.ID != owner[sub] {
265				t.Fatalf("提交人 %x 重放：id=%d err=%v，要 %d",
266					sub, replayID(j), err, owner[sub])
267			}
268			// 列举只按完整字符串匹配：每个提交人只能看到自己那一条。
269			list, err := s2.List(sub, time.Time{}, time.Time{})
270			if err != nil {
271				t.Fatal(err)
272			}
273			if len(list) != 1 || list[0].ID != owner[sub] {
274				var ids []uint64
275				for _, got := range list {
276					ids = append(ids, got.ID)
277				}
278				t.Fatalf("List(%x)=%v，要只含作业 %d", sub, ids, owner[sub])
279			}
280			if list[0].Submitter != sub || list[0].RequestID != commonReq {
281				t.Fatalf("List(%x) 视图标失真：%x / %x",
282					sub, list[0].Submitter, list[0].RequestID)
283			}
284		}
285	}
286	
287	// TestInvalidUTF8EmptyAndNULOnlyRequestIDDistinction ：空请求号不启用幂等、
288	// 只含零字符的请求号启用幂等——这一区别在提交人含非法字节时保持不变。
289	func TestInvalidUTF8EmptyAndNULOnlyRequestIDDistinction(t *testing.T) {
290		s, _ := openTestStore(t)
291		sub := "dave\xff"
292	
293		nulOnly := mustSubmit(t, s, SubmitRequest{
294			Submitter: sub, RequestID: "\x00", Values: []int64{1},
295		})
296		waitStatus(t, s, nulOnly.ID, StatusSucceeded)
297		again, err := s.Submit(SubmitRequest{
298			Submitter: sub, RequestID: "\x00", Values: []int64{1},
299		})
300		if err != nil || again.ID != nulOnly.ID {
301			t.Fatalf("零字符请求号重放：id=%d err=%v，要 %d",
302				replayID(again), err, nulOnly.ID)
303		}
304	
305		e1 := mustSubmit(t, s, SubmitRequest{Submitter: sub, RequestID: "", Values: []int64{1}})
306		e2 := mustSubmit(t, s, SubmitRequest{Submitter: sub, RequestID: "", Values: []int64{1}})
307		if e1.ID == e2.ID {
308			t.Fatal("空请求号即使提交人含非法字节也不应启用幂等")
309		}
310		waitStatus(t, s, e1.ID, StatusSucceeded)
311		waitStatus(t, s, e2.ID, StatusSucceeded)
312	}
313	
314	// TestIdentityRawEncodingRoundTrip 直接覆盖编码兜底规则：
315	//   - 合法 UTF-8（含零字符与普通中文）不产生 identity_raw，落盘格式与旧版一致；
316	//   - 含非法字节时写入 identity_raw，且可逐字节恢复；
317	//   - 看起来像 base64 的普通文本（"abcd"）不会被误判为兜底编码。
318	func TestIdentityRawEncodingRoundTrip(t *testing.T) {
319		cases := []struct {
320			submitter string
321			requestID string
322		}{
323			{"alice", "r-1"},
324			{"张三", "请求号\x00续"},
325			{"a", "b\x00c"},
326			{"a\x00b", "c"},
327			{"\xff", "abcd"}, // "abcd" 恰为合法 base64，验证前缀无歧义
328			{mixedIdentitySub, mixedIdentityReq},
329			{"", "\xff"}, // 空提交人 + 非法字节请求号
330		}
331		for i, c := range cases {
332			j := &storedJob{
333				id:        uint64(i + 1),
334				submitter: c.submitter,
335				requestID: c.requestID,
336				seed:      1,
337				values:    []int64{1},
338				status:    StatusQueued,
339			}
340			data, err := encodeRecord(j)
341			if err != nil {
342				t.Fatalf("case %d encode: %v", i, err)
343			}
344			wantRaw := !utf8.ValidString(c.submitter) || !utf8.ValidString(c.requestID)
345			if strings.Contains(string(data), "identity_raw") != wantRaw {
346				t.Fatalf("case %d identity_raw 存在性=%v，要 %v", i, !wantRaw, wantRaw)
347			}
348			var r jobRecord
349			if err := json.Unmarshal(data, &r); err != nil {
350				t.Fatalf("case %d decode: %v", i, err)
351			}
352			gotSub, gotReq, err := resolveIdentity(r.Submitter, r.RequestID, r.IdentityRaw)
353			if err != nil {
354				t.Fatalf("case %d resolve: %v", i, err)
355			}
356			if gotSub != c.submitter || gotReq != c.requestID {
357				t.Fatalf("case %d 往返失真：%x / %x，要 %x / %x",
358					i, gotSub, gotReq, c.submitter, c.requestID)
359			}
360		}
361	}
362	
363	// TestLegacyPlainAndNULArchivesOpenWithoutConversion ：旧格式记录
364	// （没有 identity_raw 字段，标识含零字符）无需转换即可继续打开并生效。
365	func TestLegacyPlainAndNULArchivesOpenWithoutConversion(t *testing.T) {
366		dir := t.TempDir()
367		queuedAt := time.Date(2026, 1, 1, 0, 0, 0, 0, time.UTC)
368		data, err := encodeRecord(&storedJob{
369			id: 1, submitter: "a", requestID: "b\x00c",
370			seed: 2, values: []int64{8}, queuedAt: queuedAt, status: StatusQueued,
371		})
372		if err != nil {
373			t.Fatal(err)
374		}
375		if strings.Contains(string(data), "identity_raw") {
376			t.Fatal("含零字符的合法 UTF-8 标识不应写出 identity_raw")
377		}
378		if err := writeFileAtomic(dir, jobFileName(1), data, 0o600); err != nil {
379			t.Fatal(err)
380		}
381	
382		s, err := Open(dir)
383		if err != nil {
384			t.Fatal(err)
385		}
386		defer s.Close()
387		g, err := s.Get(1)
388		if err != nil {
389			t.Fatal(err)
390		}
391		if g.Submitter != "a" || g.RequestID != "b\x00c" {
392			t.Fatalf("旧记录标识失真：%x / %x", g.Submitter, g.RequestID)
393		}
394		// 旧归档中的幂等号继续生效。
395		replay, err := s.Submit(SubmitRequest{
396			Submitter: "a", RequestID: "b\x00c", Values: []int64{8}, Seed: 2,
397		})
398		if err != nil || replay.ID != 1 {
399			t.Fatalf("旧记录幂等号未恢复：id=%d err=%v，要 1", replayID(replay), err)
400		}
401	}
