74	// gateCompute 安装计算钩子：block(id) 让指定作业停在“计算中”，
75	// release(id) 放行；未 block 的作业直接完成。started 记录进入计算的作业号，
76	// order 记录实际完成计算的顺序，计算本身仍由真实 computeResult 完成。
77	func gateCompute(t *testing.T, s *Store) (
78		started chan uint64,
79		block func(ids ...uint64),
80		release func(id uint64),
81		order *[]uint64,
82		omu *sync.Mutex,
83	) {
84		t.Helper()
85		started = make(chan uint64, 64)
86		var bmu sync.Mutex
87		gates := make(map[uint64]chan struct{})
88		var ord []uint64
89		omu = &sync.Mutex{}
90		block = func(ids ...uint64) {
91			bmu.Lock()
92			defer bmu.Unlock()
93			for _, id := range ids {
94				gates[id] = make(chan struct{})
95			}
96		}
97		release = func(id uint64) {
98			bmu.Lock()
99			ch, ok := gates[id]
100			bmu.Unlock()
101			if ok {
102				close(ch)
103			}
104		}
105		s.compute = func(id uint64, inputs []int64, seed int64, canceled func() bool) (int64, int64, string, bool) {
106			started <- id
107			bmu.Lock()
108			ch := gates[id]
109			bmu.Unlock()
110			if ch != nil {
111				select {
112				case <-ch:
113				case <-s.stopCh: // Close 时自动放行，真实计算随后观察到取消而中止
114				}
115			}
116			omu.Lock()
117			ord = append(ord, id)
118			omu.Unlock()
119			return computeResult(inputs, seed, canceled)
120		}
121		return started, block, release, &ord, omu
122	}
