func TestBasicSuccessAndArchive(t *testing.T) {
	s, _ := openTestStore(t)
	j := mustSubmit(t, s, SubmitRequest{
		Submitter: "alice", RequestID: "req-1", Values: []int64{1, 2, 3, -4}, Seed: 7,
	})
