	var wg sync.WaitGroup
	ids := make([]uint64, n)
	errs := make([]error, n)
	start := make(chan struct{})
	for i := 0; i < n; i++ {
		wg.Add(1)
		go func(i int) {
			defer wg.Done()
			<-start
			j, err := s.Submit(SubmitRequest{
				Submitter: "a", RequestID: "race", Values: []int64{1, 2, 3},
			})
