	}
	if len(uniq) != 1 {
		t.Fatalf("created %d jobs under one idempotency key: %v", len(uniq), ids)
	}
	waitStatus(t, s, ids[0], StatusSucceeded)
	if got, _ := s.List("a", time.Time{}, time.Time{}); len(got) != 1 {
		t.Fatalf("expected exactly 1 record, got %d", len(got))
