185			t.Fatal("\"\\x00\" 与 \"\\x00\\x00\" 被当成同一请求号")
186		}
187		waitStatus(t, s, twoNULs.ID, StatusSucceeded)
188	
189		// 空请求号不启用幂等：每次合法提交都创建新作业。
190		e1 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "", Values: []int64{5}})
191		e2 := mustSubmit(t, s, SubmitRequest{Submitter: "a", RequestID: "", Values: []int64{5}})
192		if e1.ID == e2.ID {
193			t.Fatal("空请求号的重复提交不应命中幂等")
194		}
195		waitStatus(t, s, e1.ID, StatusSucceeded)
196		waitStatus(t, s, e2.ID, StatusSucceeded)
197	}
